import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, vec3, positionLocal, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, BoxGeometry, DirectionalLight, Color } = ctx.THREE;

  const COL = {
    background: '#0b0b10',
    surface: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    gradTop: '#1a1a22',
    gradBottom: '#111116',
    border: '#26262f'
  };

  const root = new Group();
  root.userData.handlers = {};
  const disposables = [];
  const timelines = [];
  const primitiveCleanups = [];

  // ---- backdrop stage plane ----
  const backdrop = new Mesh(new PlaneGeometry(7, 6), (() => {
    const m = new MeshBasicNodeMaterial();
    const t = uv().y;
    m.colorNode = mix(vec3(...new Color(COL.gradBottom).toArray()), vec3(...new Color(COL.gradTop).toArray()), smoothstep(0.0, 1.0, t));
    return m;
  })());
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  disposables.push(backdrop.geometry, backdrop.material);

  // ---- panel ----
  const PANEL_W = 3.4, PANEL_H = 1.9;
  const panelGroup = new Group();
  root.add(panelGroup);

  const panelMat = new MeshStandardNodeMaterial();
  panelMat.roughness = 0.6;
  panelMat.metalness = 0.2;
  panelMat.clearcoat = 0.1;
  {
    const t = uv().y;
    panelMat.colorNode = mix(vec3(...new Color(COL.gradBottom).toArray()), vec3(...new Color(COL.gradTop).toArray()), smoothstep(0.0, 1.0, t));
  }
  const panel = new Mesh(new PlaneGeometry(PANEL_W, PANEL_H), panelMat);
  panelGroup.add(panel);
  disposables.push(panel.geometry, panelMat);

  // hairline border (slightly larger plane behind, accent-neutral)
  const borderMat = new MeshBasicNodeMaterial();
  borderMat.colorNode = vec3(...new Color(COL.border).toArray());
  const border = new Mesh(new PlaneGeometry(PANEL_W + 0.012, PANEL_H + 0.012), borderMat);
  border.position.z = -0.005;
  panelGroup.add(border);
  disposables.push(border.geometry, borderMat);

  // ---- oversized quotation mark (extruded box glyph via text) ----
  const markMat = new MeshStandardNodeMaterial();
  markMat.roughness = 0.5;
  markMat.metalness = 0.3;
  markMat.colorNode = vec3(...new Color(COL.accent).toArray());

  const markGroup = new Group();
  panelGroup.add(markGroup);

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  const padX = -PANEL_W / 2 + 0.5;
  const topY = PANEL_H / 2 - 0.5;

  // Quote mark glyph rendered as accent MSDF text, extruded look via z offset + backing bar
  const markText = ctx.fontAtlas.createText('"', { fontSize: 90, color: COL.accent, align: 'left' });
  markText.position.set(padX, topY, 0.04);
  markGroup.add(markText);

  // ---- quote body ----
  const quoteStr = items.find((i) => i.role === 'quote')?.text
    ?? 'The bezel action alone is worth the wait. Nothing else on my wrist feels this considered.';
  const quote = ctx.fontAtlas.createText(quoteStr, {
    fontSize: 28,
    color: COL.paper,
    align: 'left',
    maxWidthPx: 480
  });
  quote.position.set(padX, topY - 0.25, 0.03);
  panelGroup.add(quote);

  // ---- accent rule ----
  const ruleMat = new MeshStandardNodeMaterial();
  ruleMat.color = new Color(COL.accent);
  ruleMat.emissive = new Color(COL.accent);
  ruleMat.emissiveIntensity = 1.4;
  ruleMat.roughness = 0.5;
  ruleMat.metalness = 0.2;
  const rule = new Mesh(new PlaneGeometry(0.2, 0.02), ruleMat);
  const attrY = -PANEL_H / 2 + 0.55;
  rule.position.set(padX + 0.1, attrY + 0.05, 0.03);
  panelGroup.add(rule);
  disposables.push(rule.geometry, ruleMat);

  // ---- attribution ----
  const attrStr = items.find((i) => i.role === 'attribution')?.text ?? 'M. OKAFOR';
  const attr = ctx.fontAtlas.createText(attrStr, {
    fontSize: 18,
    color: COL.paper,
    align: 'left',
    letterSpacingPx: 1.5
  });
  attr.position.set(padX + 0.35, attrY + 0.05, 0.03);
  panelGroup.add(attr);

  const capStr = items.find((i) => i.role === 'caption')?.text ?? 'COLLECTOR SINCE 2019';
  const cap = ctx.fontAtlas.createText(capStr, {
    fontSize: 12,
    color: '#8a8a95',
    align: 'left',
    letterSpacingPx: 2
  });
  cap.position.set(padX + 0.35, attrY - 0.12, 0.03);
  panelGroup.add(cap);

  // ---- lighting: rim/accent (scene provides ambient + key) ----
  const rim = new DirectionalLight(new Color(COL.accent), 0.7);
  rim.position.set(-3, 1.5, 2);
  root.add(rim);

  const fill = new DirectionalLight(new Color('#ffffff'), 0.5);
  fill.position.set(3, 2.5, 3);
  root.add(fill);

  // ---- entrance motion ----
  panelGroup.position.y = 0.2;
  const setOpacity = (o) => {
    panelMat.opacity = o; panelMat.transparent = o < 1;
    borderMat.opacity = o; borderMat.transparent = o < 1;
  };
  setOpacity(0);

  const tlPanel = gsap.timeline();
  tlPanel.to(panelGroup.position, { y: 0, duration: 0.5, ease: 'power2.out' }, 0);
  tlPanel.to({ o: 0 }, {
    o: 1, duration: 0.5, ease: 'power2.out',
    onUpdate: function () { setOpacity(this.targets()[0].o); }
  }, 0);
  timelines.push(tlPanel);

  markGroup.scale.setScalar(1.04);
  const tlMark = gsap.timeline({ delay: 0.5 });
  tlMark.to(markGroup.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' });
  timelines.push(tlMark);

  root.userData.cleanup = () => {
    timelines.forEach((t) => t.kill());
    primitiveCleanups.forEach((c) => c && c());
    disposables.forEach((d) => d && d.dispose && d.dispose());
  };

  return root;
}
